  "the reply has {n} rows, more than the {max} asked for": { one: "la respuesta tiene {n} fila, más de las {max} que se pidieron", many: "la respuesta tiene {n} filas, más de las {max} que se pidieron", other: "la respuesta tiene {n} filas, más de las {max} que se pidieron" },
